args.sparql:
SELECT DISTINCT ?father ?fatherLabel WHERE {
  dbr:Grand_Duchess_Elena_Vladimirovna_of_Russia (dbp:father|dbo:parent) ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel . FILTER(lang(?fatherLabel) = 'en') }
}

SELECT DISTINCT ?deathPlace ?deathPlaceLabel WHERE {
  dbr:Grand_Duke_Vladimir_Alexandrovich_of_Russia (dbp:deathPlace|dbo:deathPlace|dbp:placeOfDeath) ?deathPlace .
  OPTIONAL { ?deathPlace rdfs:label ?deathPlaceLabel . FILTER(lang(?deathPlaceLabel) = 'en') }
}

SELECT DISTINCT ?father ?fatherLabel ?deathPlaceIRI ?deathPlaceLabel ?deathPlaceLiteral WHERE {
  dbr:Grand_Duchess_Elena_Vladimirovna_of_Russia (dbp:father|dbo:parent) ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER(lang(?fatherLabel)='en') }
  OPTIONAL { ?father dbp:deathPlace ?deathPlaceLiteral . }
  OPTIONAL { ?father dbo:deathPlace ?deathPlaceIRI . }
  OPTIONAL { ?deathPlaceIRI rdfs:label ?deathPlaceLabel FILTER(lang(?deathPlaceLabel)='en') }
  OPTIONAL {
    ?candidate rdfs:label ?candidateLabel FILTER(lang(?candidateLabel)='en') .
    FILTER(bound(?deathPlaceLiteral) && CONTAINS(LCASE(?candidateLabel), LCASE(STRBEFORE(STR(?deathPlaceLiteral),',')))) .
    BIND(?candidate AS ?deathPlaceIRI)
  }
}

SELECT DISTINCT ?father ?fatherLabel ?deathPlace WHERE {
  dbr:Grand_Duchess_Elena_Vladimirovna_of_Russia (dbp:father|dbo:parent) ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER (lang(?fatherLabel) = 'en') }
  OPTIONAL { ?father dbp:deathPlace ?deathPlace }
}

SELECT DISTINCT ?father ?fatherLabel ?deathPlace WHERE {
  dbr:Grand_Duchess_Elena_Vladimirovna_of_Russia (dbp:father|dbo:parent) ?father .
  OPTIONAL { ?father rdfs:label ?fatherLabel FILTER (lang(?fatherLabel) = 'en') }
  OPTIONAL { ?father dbp:deathPlace ?deathPlace }
}

